/**
 * PRD-2.5 §3.6 WP-VERSUS anomaly signals (pure; no Firestore).
 * Each crafted cheat shape raises its signal; honest shapes — hand-made and
 * the real game timelines in fixtures/honest_runs.json (generated by
 * test/versus/anomaly_fixtures_test.dart) — raise none.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { Timestamp } from 'firebase-admin/firestore';
import { passBound, runFacts, scoreRun } from '../src/anomaly.js';
import {
  FLAG_BONUS,
  FLAG_GIFT,
  FLAG_PUZZLE,
  FLAG_RIDE,
  FLAG_TRAIN,
  PACE_MIN_GAPS,
  PACE_MIN_MEDIAN_CS,
  RunEntry,
} from '../src/schema.js';
import { checkRun } from '../src/timeline.js';
import { LOOK, makeRun } from './helpers.js';

const P = 0; // a plain pass

/** A run from (delta cs, flag, value) triples; score = Σ values. */
function shaped(entries: [number, number, number][], end = 80): RunEntry {
  const deltas = entries.map((e) => e[0]);
  const flags = entries.map((e) => e[1]);
  const values = entries.map((e) => e[2]);
  return makeRun({ score: values.reduce((a, b) => a + b, 0), deltas, flags, values, end });
}

/** [n] plain perfect passes [gap] cs apart with the streak 1..n (value max(2, k)). */
function perfectRun(n: number, gap = 170, chickFrom = Infinity): RunEntry {
  return shaped(Array.from({ length: n }, (_, i) => [gap, P, Math.max(2, i + 1) + (i + 1 >= chickFrom ? 1 : 0)]));
}

function assertHonest(run: RunEntry, hist: number[] = [], why = '') {
  assert.equal(checkRun(run, run.best), null, `checkRun ${why}`);
  assert.equal(scoreRun(run, hist), null, `anomaly on an honest run ${why}: ${JSON.stringify(scoreRun(run, hist))}`);
}

describe('PRD-2.5 §3.6 anomaly: honest shapes raise nothing', () => {
  it('an all-perfect streak 1..120 at top speed, with and without the chick', () => {
    assertHonest(perfectRun(120));
    assertHonest(perfectRun(120, 170, 30), [], 'chick hatches at pass 30');
  });

  it('non-perfect passes, streak breaks and restarts', () => {
    const e: [number, number, number][] = [];
    for (let k = 0; k < 60; k++) e.push([180, P, k % 10 === 9 ? 1 : Math.max(2, (k % 10) + 1)]);
    assertHonest(shaped(e));
  });

  it('a FEVER jump (streak → 5) right after a broken streak, with the chick (2 → 7)', () => {
    // pass 1 (non-perfect, chick +1) = 2; FEVER pass = max(2, 1) + 1 = 3; next = 6 + 1 = 7.
    assertHonest(shaped([[200, P, 2], [180, P, 3], [180, P, 7], [180, P, 8], [180, P, 9]]));
    // Without the chick: 1 → 2 (FEVER) → 6.
    assertHonest(shaped([[200, P, 1], [180, P, 2], [180, P, 6], [180, P, 7]]));
  });

  it('the pair FEVER gift (+5, streak ≥ 5) after a non-perfect pass', () => {
    assertHonest(shaped([[200, P, 1], [150, P, 1], [10, FLAG_GIFT, 5], [180, P, 6], [180, P, 7]]));
  });

  it('Ring Train triples, rides, bonuses and the puzzle payout', () => {
    const e: [number, number, number][] = [];
    let k = 0;
    for (let slot = 0; slot < 40; slot++) {
      if (slot % 4 === 1) {
        for (let r = 0; r < 3; r++) e.push([r === 0 ? 170 : 25, FLAG_TRAIN, Math.max(2, ++k)]);
      } else if (slot % 7 === 3) {
        for (let r = 0; r < 4; r++) e.push([r === 0 ? 170 : 60, FLAG_RIDE, Math.max(2, ++k)]);
      } else {
        e.push([170, P, Math.max(2, ++k)]);
      }
      if (slot % 5 === 2) e.push([30, FLAG_BONUS, 40]);
    }
    e.push([50, FLAG_BONUS | FLAG_PUZZLE, 250]);
    assertHonest(shaped(e));
  });

  it('slow hourglass gaps and a short first run with no history', () => {
    assertHonest(shaped(Array.from({ length: 20 }, () => [320, P, 1] as [number, number, number])));
    assertHonest(makeRun({ score: 5 }), []);
  });

  it('honest 20 → 60 → 140 hoops, and 140 after a full earlier history, raise no jump', () => {
    const passHist: number[] = [];
    for (const passes of [20, 60, 140]) {
      const run = perfectRun(passes);
      assert.equal(scoreRun(run, passHist), null, `${passes} hoops`);
      passHist.push(passes);
    }
    // 140 > 4 × 20, but below the 150-pass minimum.
    assertHonest(perfectRun(140), [20, 20, 20, 20, 20]);
  });

  it('a big point jump from the uncapped streak with modest passes is not judged', () => {
    const run = perfectRun(40); // 821 points, but only 40 passes
    assert.ok(run.score > 500);
    assertHonest(run, [1, 1, 1, 1, 1]);
  });
});

describe('PRD-2.5 §3.6 anomaly: honest game timelines (fixtures/honest_runs.json)', () => {
  const file = join(__dirname, 'fixtures', 'honest_runs.json');
  const runs = JSON.parse(readFileSync(file, 'utf8')).runs as Array<{
    name: string;
    score: number;
    best: number;
    tl: string;
    fl: string;
    end: number;
  }>;

  it('has the autopilot runs (seeds × 568 / 711, FEVER, train, pair, chick, comet, portal, bonuses)', () => {
    assert.ok(runs.length >= 40, `${runs.length} runs`);
    for (const k of ['fever', 'train', 'pair', 'chick', 'comet', 'portal', 'bonuses', 'hourglass', 'fast']) {
      assert.ok(runs.some((r) => r.name.includes(k)), k);
    }
  });

  it('every honest run passes checkRun and raises zero flags (also judged with its predecessors as history)', () => {
    const passHist: number[] = [];
    let minMedian = Infinity;
    let maxPassRatio = 0;
    for (const f of runs) {
      const run: RunEntry = {
        runId: f.name,
        score: f.score,
        best: f.best,
        ts: Timestamp.now(),
        name: 'Fixture',
        avatar: '',
        look: LOOK,
        platform: 'android',
        tl: f.tl,
        end: f.end,
        fl: f.fl,
      };
      assert.equal(checkRun(run, run.best), null, f.name);
      assert.equal(scoreRun(run, []), null, `${f.name}: ${JSON.stringify(scoreRun(run, []))}`);
      const withHist = scoreRun(run, passHist.slice(-10));
      assert.equal(withHist, null, `${f.name} (history): ${JSON.stringify(withHist)}`);
      const facts = runFacts(run)!;
      passHist.push(facts.passes);
      if (facts.paceGaps >= PACE_MIN_GAPS) minMedian = Math.min(minMedian, facts.paceMedianCs!);
      maxPassRatio = Math.max(maxPassRatio, facts.passes / facts.passBound);
    }
    // Headroom report (shown on failure only): the honest pace stays well above the threshold.
    assert.ok(minMedian >= PACE_MIN_MEDIAN_CS, `min honest median ${minMedian} cs`);
    assert.ok(maxPassRatio <= 1, `max passes / bound ${maxPassRatio}`);
  });
});

describe('PRD-2.5 §3.6 anomaly: crafted cheat shapes', () => {
  it('streak_jump: a pass worth more than max(previous + 3, 8)', () => {
    const r = shaped([[200, P, 2], [180, P, 3], [180, P, 9]]);
    assert.equal(checkRun(r, r.best), null); // passes the old filter (cap 2 × (3 + 5) = 16)
    const a = scoreRun(r, []);
    assert.equal(a?.signals.streak_jump, 9);
    assert.equal(a?.soft, false);
    // A big step later in a run (streak 10 → 14).
    assert.equal(scoreRun(shaped([[200, P, 8], [180, P, 9], [180, P, 10], [180, P, 14]]), [])?.signals.streak_jump, 14);
    // A huge streak right away (first pass worth 9).
    assert.equal(scoreRun(shaped([[200, P, 9], [180, P, 10]]), [])?.signals.streak_jump, 9);
    // The honest edge: + 3 and the FEVER floor 8 pass.
    assert.equal(scoreRun(shaped([[200, P, 8], [180, P, 9], [180, P, 10], [180, P, 13]]), []), null);
    assert.equal(scoreRun(shaped([[200, P, 1], [180, P, 8]]), []), null);
  });

  it('pace: plain passes every 1.2 s (a sped-up client)', () => {
    const r = shaped(Array.from({ length: 30 }, () => [120, P, 1] as [number, number, number]));
    assert.equal(checkRun(r, r.best), null); // ≥ 0.9 s gaps: the old filter lets it through
    assert.equal(scoreRun(r, [])?.signals.pace, 120);
    // Under PACE_MIN_GAPS plain gaps: not judged.
    assert.equal(scoreRun(shaped(Array.from({ length: PACE_MIN_GAPS }, () => [120, P, 1] as [number, number, number])), []), null);
  });

  it('passes: more rings than the scroll can bring (train flags spammed)', () => {
    // 200 "train" passes in 60 s: the bound is 3 × ⌈60 × 187.5 / 310⌉ + 5 = 116.
    const r = shaped(Array.from({ length: 200 }, () => [30, FLAG_TRAIN, 1] as [number, number, number]), 0);
    assert.equal(passBound(6000), 116);
    assert.equal(checkRun(r, r.best), null);
    assert.equal(scoreRun(r, [])?.signals.passes, 200);
  });

  it('jump (soft): ≥ 150 passes and > 4 × the median of ≥ 5 earlier pass counts', () => {
    const r = perfectRun(150);
    const a = scoreRun(r, [20, 30, 25, 40, 35]);
    assert.equal(a?.signals.jump, 30);
    assert.equal(a?.soft, true);
    // The threshold is strict: 150 is not more than 4 × a median of 37.5.
    assert.equal(scoreRun(r, [20, 20, 20, 55, 55, 55]), null);
    assert.equal(scoreRun(perfectRun(151), [20, 20, 20, 55, 55, 55])?.signals.jump, 37.5);
    // Fewer than five earlier pass counts are never judged.
    assert.equal(scoreRun(perfectRun(200), [1, 1, 1, 1]), null);
    // 149 passes stay below the minimum even with a tiny median.
    assert.equal(scoreRun(perfectRun(149), [1, 1, 1, 1, 1]), null);
    // Combined with a hard signal the flag is hard.
    const hard = shaped([...Array.from({ length: 150 }, () => [170, P, 1] as [number, number, number]), [170, P, 9]]);
    const bothHard = scoreRun(hard, [1, 1, 1, 1, 1]);
    assert.ok(bothHard?.signals.jump !== undefined && bothHard.signals.streak_jump === 9);
    assert.equal(bothHard?.soft, false);
  });

  it('a malformed timeline is not judged here (checkRun rejects it)', () => {
    assert.equal(scoreRun({ ...makeRun(), tl: '!!' }, []), null);
  });
});
